def maxBalancedSubsequenceSum(nums):
    n = len(nums)
    b = [nums[i] - i for i in range(n)]
    comp = sorted(set(b))
    rank = {v: i + 1 for i, v in enumerate(comp)}
    m = len(comp)
    NEG = float('-inf')
    tree = [NEG] * (m + 1)

    def update(i, val):
        while i <= m:
            if val > tree[i]:
                tree[i] = val
            i += i & (-i)

    def query(i):
        res = NEG
        while i > 0:
            if tree[i] > res:
                res = tree[i]
            i -= i & (-i)
        return res

    ans = NEG
    for i in range(n):
        r = rank[b[i]]
        prev = query(r)
        best_prev = prev if prev > 0 else 0
        dp = nums[i] + best_prev
        update(r, dp)
        if dp > ans:
            ans = dp
    return ans
